    spNameTeamUp: 'ಟೀಮ್ ಅಪ್',
    spNameFrontRow: 'ಮುಂಭಾಗದ ಸಾಲು',
    spDescFrontRow: 'ಹಂತಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡುವ ಪ್ರತಿಯೊಂದು ಮೇಲ್ಮೈಯಲ್ಲೂ ನಿಮ್ಮ ಲೈವ್ ಹಂತವು ರೈಲು ಚಲಿಸುವಾಗ ಹಂತಗಳ ಮೇಲ್ಭಾಗವನ್ನು ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ.',
    spNameDeepCurrent: 'ಡೀಪ್ ಕರೆಂಟ್',
