    contactItem3: 'DAO ಮೂಲಕ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ಸಲ್ಲಿಸಿ',
    contactNote: 'ಸಮುದಾಯ ಆಡಳಿತ ಪ್ರಕ್ರಿಯೆಗಳ ಮೂಲಕ ಈ ಗೌಪ್ಯತೆ ನೀತಿಯನ್ನು ನವೀಕರಿಸಬಹುದು. ವಸ್ತು ಬದಲಾವಣೆಗಳನ್ನು ನಮ್ಮ ಅಧಿಕೃತ ಚಾನಲ್‌ಗಳ ಮೂಲಕ ತಿಳಿಸಲಾಗುತ್ತದೆ.',
    importantNotice: 'ಪ್ರಮುಖ ಸೂಚನೆ',
    importantNoticeText: 'DeHub ವಿಕೇಂದ್ರೀಕೃತ ಪ್ರೋಟೋಕಾಲ್ ಆಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ. ನಾವು ಬಳಕೆದಾರರ ಗೌಪ್ಯತೆಯನ್ನು ರಕ್ಷಿಸಲು ಶ್ರಮಿಸುತ್ತಿರುವಾಗ, ವಿಕೇಂದ್ರೀಕೃತ ಸ್ವಭಾವವೆಂದರೆ ಸಾರ್ವಜನಿಕ ಬ್ಲಾಕ್‌ಚೈನ್‌ಗಳಲ್ಲಿ ಸಂವಹನಗಳು ಗೋಚರಿಸಬಹುದು. ಬಳಕೆದಾರರು ತಮ್ಮ ಬ್ಲಾಕ್‌ಚೈನ್ ಸಂವಹನಗಳ ಗೌಪ್ಯತೆ ಪರಿಣಾಮಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವ ಜವಾಬ್ದಾರಿಯನ್ನು ಹೊಂದಿರುತ್ತಾರೆ.',
    lastUpdatedDate: '29 ಸೆಪ್ಟೆಂಬರ್ 2026',
    doCollectItem1: 'ನೀವು ಸೈನ್ ಇನ್ ಮಾಡಿದ ಗುರುತಿಸುವಿಕೆ — ನೀವು ಆ ಮಾರ್ಗಗಳಲ್ಲಿ ಒಂದನ್ನು ಆರಿಸಿದರೆ ಇಮೇಲ್ ವಿಳಾಸ ಅಥವಾ ಫೋನ್ ಸಂಖ್ಯೆ, ನೀವು ಸಾಮಾಜಿಕವಾಗಿ ಸೈನ್ ಇನ್ ಮಾಡಿದರೆ Google, Apple ಅಥವಾ Telegram ಗುರುತಿಸುವಿಕೆ ಅಥವಾ ಪಾಸ್‌ಕೀ ಸಾರ್ವಜನಿಕ ರುಜುವಾತು. ವಾಲೆಟ್ ಸೈನ್-ಇನ್ ನಿಮ್ಮ ಸಾರ್ವಜನಿಕ ವಿಳಾಸವನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೇನೂ ನಮಗೆ ನೀಡುವುದಿಲ್ಲ.',
    doCollectItem7: 'ನೀವು ಬದಲಾಯಿಸಲು ಆಯ್ಕೆ ಮಾಡಿದ ವಿಷಯಗಳು: ಪಠ್ಯ ಅಧಿಸೂಚನೆಗಳಿಗಾಗಿ ಫೋನ್ ಸಂಖ್ಯೆ, ನೀವು ಆನ್‌ಲೈನ್‌ನಲ್ಲಿರುವಾಗ ಇತರರು ನೋಡುತ್ತಾರೆಯೇ ಮತ್ತು ಬಹು-ಪೋಸ್ಟಿಂಗ್‌ಗಾಗಿ ನೀವು ಸಂಪರ್ಕಿಸುವ ಬಾಹ್ಯ ಸಾಮಾಜಿಕ ಖಾತೆಗಳು.',
    doCollectItem8: 'ಯಾವ ಪುಟಗಳಿಗೆ ಭೇಟಿ ನೀಡಲಾಗುತ್ತದೆ ಮತ್ತು ಜನರು ಅವುಗಳ ನಡುವೆ ಹೇಗೆ ಚಲಿಸುತ್ತಾರೆ ಎಂಬುದನ್ನು ನಾವು ನೋಡಬಹುದು. ನಿಮ್ಮ ಅಂಗಸಂಸ್ಥೆ ಪುಟಗಳಿಗೆ ನಿಮ್ಮ ಸ್ವಂತ ಭೇಟಿಗಳನ್ನು ಪರಿಗಣಿಸಲಾಗುವುದಿಲ್ಲ.',
    dontCollectItem6: 'ನಿಮ್ಮ ಕಾರ್ಡ್ ವಿವರಗಳು ಮತ್ತು ನಿಮ್ಮ ಅಂತ್ಯ-ಮುಕ್ತವಾಗಿ ಎನ್ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾದ ನೇರ ಸಂದೇಶಗಳ ಪಠ್ಯ — ಅವುಗಳನ್ನು ನಾವು ಓದಲು ಸಾಧ್ಯವಿಲ್ಲ. ಸಂದೇಶಗಳಲ್ಲಿ ಫೋಟೋಗಳು, ವೀಡಿಯೋಗಳು ಮತ್ತು ಫೈಲುಗಳು, ಮತ್ತು ಎನ್ಕ್ರಿಪ್ಷನ್ ಅನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡದವನಿಗೆ ಸಂದೇಶಗಳು, ಇನ್ನೂ ಅಂತ್ಯ-ಮುಕ್ತವಾಗಿ ಎನ್ಕ್ರಿಪ್ಟ್ ಆಗಿಲ್ಲ.',
    thirdPartyItem6: 'DeHub ನ ಸ್ವಂತ ಸೇವನೆಯು ಲೈವ್ ವೀಡಿಯೊವನ್ನು ಹೊಂದಿದೆ, ಲೈವ್‌ಪೀರ್ ಅನ್ನು ಫಾಲ್‌ಬ್ಯಾಕ್ ಆಗಿ ಹೊಂದಿದೆ ಮತ್ತು ಅಗೋರಾ ಲೈವ್ ಆಡಿಯೊ ಕೊಠಡಿಗಳನ್ನು ಹೊಂದಿದೆ',
    thirdPartyItem8: 'ಪೀಳಿಗೆ, ಅನುವಾದ, ಶೀರ್ಷಿಕೆ ಅಥವಾ ಡಬ್ಬಿಂಗ್ ವೈಶಿಷ್ಟ್ಯಕ್ಕೆ ನೀವು ಕಳುಹಿಸುವ ಪಠ್ಯ ಮತ್ತು ಮಾಧ್ಯಮವನ್ನು ಅದನ್ನು ಚಾಲನೆ ಮಾಡುವ ಪೂರೈಕೆದಾರರಿಗೆ ರವಾನಿಸಲಾಗುತ್ತದೆ, ಆ ವಿನಂತಿಗಾಗಿ ಮಾತ್ರ. ಖಾಸಗಿ ಪಠ್ಯ — ಸಂದೇಶಗಳು, ಪ್ರತ್ಯುತ್ತರಗಳು ಮತ್ತು ಸಹಾಯಕ ಚಾಟ್‌ಗಳು — ಒದಗಿಸುವವರಿಗೆ ಅದು ಸ್ವೀಕರಿಸುವದರ ಮೇಲೆ ಉಚಿತ ಶ್ರೇಣಿ ರೈಲುಗಳನ್ನು ಎಂದಿಗೂ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.',
